class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = RollingWindow[float](101)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

        # The system specifies a percentage without supplying a numeric value;
        # the complete portfolio percentage is used for Strategy A.
        self.spy_portfolio_percentage = 1.0

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            self.spy_closes.Add(float(data.Bars[spy].Close))

        if data.Bars.ContainsKey(aapl):
            aapl_close = float(data.Bars[aapl].Close)
            self.aapl_rsi.Update(data.Bars[aapl].EndTime, aapl_close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if not self.spy_closes.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close_today = self.spy_closes[0]
        spy_close_yesterday = self.spy_closes[1]
        spy_sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
        spy_sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

        spy_crossed_below = (
            spy_close_yesterday >= spy_sma_yesterday
            and spy_close_today < spy_sma_today
        )
        spy_crossed_above = (
            spy_close_yesterday <= spy_sma_yesterday
            and spy_close_today > spy_sma_today
        )

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and not self.spy_order_pending and spy_crossed_below:
            self.spy_order_pending = True
            self.MarketOrder(spy, -self.spy_lot, tag="strategy-a-sell")

        if (
            self.aapl_lot > 0
            and not self.aapl_order_pending
            and self.aapl_rsi.Current.Value > 60
        ):
            self.aapl_order_pending = True
            self.MarketOrder(aapl, -self.aapl_lot, tag="strategy-b-sell")

        if self.spy_lot == 0 and not self.spy_order_pending and spy_crossed_above:
            quantity = self.CalculateOrderQuantity(spy, self.spy_portfolio_percentage)
            if quantity > 0:
                self.spy_order_pending = True
                self.MarketOrder(spy, quantity, tag="strategy-a-buy")

        if (
            self.aapl_lot == 0
            and not self.aapl_order_pending
            and self.aapl_red_streak >= 3
        ):
            cash = float(self.Portfolio.CashBook["USD"].Amount)
            aapl_close = float(data.Bars[aapl].Close)
            if cash >= 20_000:
                quantity = int(20_000 // aapl_close)
                if quantity > 0:
                    self.aapl_order_pending = True
                    self.MarketOrder(aapl, quantity, tag="strategy-b-buy")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (OrderStatus.Filled, OrderStatus.PartiallyFilled):
            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                ticket = self.Transactions.GetOrderTicket(order_event.OrderId)
                if ticket is not None and ticket.Tag.startswith("strategy-a-"):
                    self.spy_order_pending = False
                elif ticket is not None and ticket.Tag.startswith("strategy-b-"):
                    self.aapl_order_pending = False
            return

        ticket = self.Transactions.GetOrderTicket(order_event.OrderId)
        if ticket is None:
            return

        fill_quantity = int(order_event.FillQuantity)
        if ticket.Tag.startswith("strategy-a-"):
            self.spy_lot += fill_quantity
            if order_event.Status == OrderStatus.Filled:
                self.spy_order_pending = False
        elif ticket.Tag.startswith("strategy-b-"):
            self.aapl_lot += fill_quantity
            if order_event.Status == OrderStatus.Filled:
                self.aapl_order_pending = False

