            bars.contains_key(symbol) for symbol in self.symbols.values()
        )
        indicators_ready = (
            spy_sma is not None
            and self.previous_spy_sma is not None
            and self.aapl_rsi.is_ready
        )

        if all_bars_present and indicators_ready:
            # All sells are evaluated before either independent strategy buys.
