class ParallelDailyStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ("SPY", "AAPL", "IBM", "BAC", "AIG")
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        # Strategy A's portfolio percentage.  One represents 100%.
        self.spy_allocation = 1.0
        self.spy_closes = RollingWindow[float](101)
        self.spy_lot = 0

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        bars = data.bars

        # Market-state quantities continue to update even when another ticker's
        # bar is absent and the day's trading rules therefore have to be skipped.
        spy_bar = bars.get(self.symbols["SPY"])
        if spy_bar is not None:
            self.spy_closes.add(float(spy_bar.close))

        aapl_bar = bars.get(self.symbols["AAPL"])
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)

        if any(bars.get(self.symbols[ticker]) is None for ticker in self.tickers):
            return

        # Sells are evaluated before buys.  The two lots otherwise operate
        # independently and may both act on the same daily bar.
        self._sell_strategy_a(spy_bar)
        self._sell_strategy_b()
        self._buy_strategy_a(spy_bar)
        self._buy_strategy_b(aapl_bar)

    def _spy_crosses(self, close, direction):
        if not self.spy_closes.is_ready:
            return False

        values = [self.spy_closes[i] for i in range(101)]
        current_sma = sum(values[:100]) / 100.0
        previous_sma = sum(values[1:]) / 100.0
        previous_close = values[1]

        if direction == "above":
            return previous_close <= previous_sma and close > current_sma
        return previous_close >= previous_sma and close < current_sma

    def _sell_strategy_a(self, spy_bar):
        if self.spy_lot <= 0:
            return
        if self._spy_crosses(float(spy_bar.close), "below"):
            self.market_order(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

    def _sell_strategy_b(self):
        if self.aapl_lot <= 0 or not self.aapl_rsi.is_ready:
            return
        if float(self.aapl_rsi.current.value) > 60.0:
            self.market_order(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

    def _buy_strategy_a(self, spy_bar):
        if self.spy_lot != 0:
            return

        close = float(spy_bar.close)
        if not self._spy_crosses(close, "above"):
            return

        target_value = float(self.portfolio.total_portfolio_value) * self.spy_allocation
        quantity = int(target_value // close)
        if quantity > 0:
            self.market_order(self.symbols["SPY"], quantity)
            self.spy_lot = quantity

    def _buy_strategy_b(self, aapl_bar):
        if self.aapl_lot != 0 or self.aapl_red_streak < 3:
            return
        if float(self.portfolio.cash) < 20_000.0:
            return

        quantity = int(20_000.0 // float(aapl_bar.close))
        if quantity > 0:
            self.market_order(self.symbols["AAPL"], quantity)
            self.aapl_lot = quantity

