class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independently managed daily strategies with private share lots."""

    SPY_ALLOCATION = 1.0

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in self.tickers
        }

        self.spy_closes = RollingWindow[float](101)
        self.aapl_closes = RollingWindow[float](4)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        bars = data.Bars

        # Market-state quantities continue to update even when another ticker's
        # bar is absent and trading-rule evaluation must be skipped.
        spy_bar = bars[self.symbols["SPY"]] if bars.ContainsKey(self.symbols["SPY"]) else None
        aapl_bar = bars[self.symbols["AAPL"]] if bars.ContainsKey(self.symbols["AAPL"]) else None

        if spy_bar is not None:
            self.spy_closes.Add(float(spy_bar.Close))
        if aapl_bar is not None:
            close = float(aapl_bar.Close)
            self.aapl_closes.Add(close)
            self.aapl_rsi.Update(aapl_bar.EndTime, close)

        if any(not bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        self._run_spy_strategy()
        self._run_aapl_strategy()

    def _run_spy_strategy(self):
        if not self.spy_closes.IsReady:
            return

        today_close = self.spy_closes[0]
        yesterday_close = self.spy_closes[1]
        today_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
        yesterday_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

        crossed_below = yesterday_close >= yesterday_sma and today_close < today_sma
        crossed_above = yesterday_close <= yesterday_sma and today_close > today_sma

        # Sells are evaluated before buys, and each order changes only this lot.
        if self.spy_lot > 0:
            if crossed_below:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
            return

        if crossed_above:
            target_value = self.Portfolio.TotalPortfolioValue * self.SPY_ALLOCATION
            quantity = int(target_value / today_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _run_aapl_strategy(self):
        if not self.aapl_closes.IsReady or not self.aapl_rsi.IsReady:
            return

        if self.aapl_lot > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
            return

