class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, close-of-day strategies with separately tracked lots."""

    STRATEGY_A_PORTFOLIO_PERCENT = 1.0

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_closes = deque(maxlen=4)

        self.rsi_period = 14
        self.rsi_previous_close = None
        self.rsi_seed_gains = []
        self.rsi_seed_losses = []
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_pending = False
        self.aapl_pending = False

    def OnData(self, data: Slice):
        spy_bar = data.Bars[self.symbols["SPY"]] if data.Bars.ContainsKey(self.symbols["SPY"]) else None
        aapl_bar = data.Bars[self.symbols["AAPL"]] if data.Bars.ContainsKey(self.symbols["AAPL"]) else None

        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))
        if aapl_bar is not None:
            self.aapl_closes.append(float(aapl_bar.Close))
            self._update_aapl_rsi(float(aapl_bar.Close))

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        # Every rule waits until all state used anywhere in the system is ready.
        if len(self.spy_closes) < 101 or self.aapl_rsi is None:
            return

        previous_spy_close = self.spy_closes[-2]
        current_spy_close = self.spy_closes[-1]
        previous_spy_sma = sum(list(self.spy_closes)[:-1]) / 100.0
        current_spy_sma = sum(list(self.spy_closes)[-100:]) / 100.0

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and not self.spy_pending:
            if previous_spy_close >= previous_spy_sma and current_spy_close < current_spy_sma:
                self.spy_pending = True
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot, tag="Strategy A sell")

        if self.aapl_lot > 0 and not self.aapl_pending and self.aapl_rsi > 60.0:
            self.aapl_pending = True
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot, tag="Strategy B sell")

        if self.spy_lot == 0 and not self.spy_pending:
            if previous_spy_close <= previous_spy_sma and current_spy_close > current_spy_sma:
                target_value = self.Portfolio.TotalPortfolioValue * self.STRATEGY_A_PORTFOLIO_PERCENT
                quantity = floor(target_value / current_spy_close)
                if quantity > 0:
                    self.spy_pending = True
                    self.MarketOrder(self.symbols["SPY"], quantity, tag="Strategy A buy")

        if self.aapl_lot == 0 and not self.aapl_pending and len(self.aapl_closes) == 4:
            red_for_three_days = all(
                self.aapl_closes[index] < self.aapl_closes[index - 1]
                for index in range(1, 4)
            )
            if red_for_three_days and self.Portfolio.Cash >= 20_000:
                quantity = floor(20_000 / float(aapl_bar.Close))
                if quantity > 0:
                    self.aapl_pending = True
                    self.MarketOrder(self.symbols["AAPL"], quantity, tag="Strategy B buy")

    def OnOrderEvent(self, order_event: OrderEvent):
        symbol = order_event.Symbol
        if order_event.FillQuantity:
            if symbol == self.symbols["SPY"]:
                self.spy_lot += int(order_event.FillQuantity)
            elif symbol == self.symbols["AAPL"]:
                self.aapl_lot += int(order_event.FillQuantity)

        if order_event.Status == OrderStatus.Filled:
            if symbol == self.symbols["SPY"]:
                self.spy_pending = False
            elif symbol == self.symbols["AAPL"]:
                self.aapl_pending = False
        elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
            if symbol == self.symbols["SPY"]:
                self.spy_pending = False
            elif symbol == self.symbols["AAPL"]:
                self.aapl_pending = False

    def _update_aapl_rsi(self, close):
        if self.rsi_previous_close is None:
            self.rsi_previous_close = close
            return

        change = close - self.rsi_previous_close
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.rsi_average_gain is None:
            self.rsi_seed_gains.append(gain)
            self.rsi_seed_losses.append(loss)
            if len(self.rsi_seed_gains) == self.rsi_period:
                self.rsi_average_gain = sum(self.rsi_seed_gains) / self.rsi_period
                self.rsi_average_loss = sum(self.rsi_seed_losses) / self.rsi_period
        else:
            self.rsi_average_gain = (
                self.rsi_average_gain * (self.rsi_period - 1) + gain
            ) / self.rsi_period
            self.rsi_average_loss = (
                self.rsi_average_loss * (self.rsi_period - 1) + loss
            ) / self.rsi_period

        if self.rsi_average_gain is not None:
            if self.rsi_average_loss == 0:
                self.aapl_rsi = 100.0 if self.rsi_average_gain > 0 else 50.0
            else:
                relative_strength = self.rsi_average_gain / self.rsi_average_loss
                self.aapl_rsi = 100.0 - 100.0 / (1.0 + relative_strength)

        self.rsi_previous_close = close

