        if aapl_bar is not None:
            previous_aapl_close = self.previous_closes.get("AAPL")
            if previous_aapl_close is not None:
                if aapl_bar.close < previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        all_bars_present = len(bars) == len(self.symbols)
        indicators_ready = self.spy_sma.is_ready and self.aapl_rsi.is_ready

        if all_bars_present and indicators_ready and not self.is_warming_up:
            spy_above_sma = spy_bar.close > self.spy_sma.current.value

            if self.spy_lot > 0:
                if self.previous_spy_above_sma is True and not spy_above_sma:
                    self.market_order(self.symbols["SPY"], -self.spy_lot)
                    self.spy_lot = 0
            elif self.previous_spy_above_sma is False and spy_above_sma:
                quantity = self.calculate_order_quantity(self.symbols["SPY"], 1.0)
                if quantity > 0:
                    self.market_order(self.symbols["SPY"], quantity)
                    self.spy_lot = quantity

            if self.aapl_lot > 0:
                if self.aapl_rsi.current.value > 60:
                    self.market_order(self.symbols["AAPL"], -self.aapl_lot)
                    self.aapl_lot = 0
            elif self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
                quantity = int(20_000 // aapl_bar.close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

        if spy_bar is not None and self.spy_sma.is_ready:
            self.previous_spy_above_sma = spy_bar.close > self.spy_sma.current.value

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.close

