                and spy_bar.close > current_spy_sma
            )
            if crossed_above:
                quantity = floor(
                    self.portfolio.total_portfolio_value
                    * self.SPY_ALLOCATION
                    / spy_bar.close
                )
                if quantity > 0:
                    self.market_order(spy, quantity)
                    self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
