            if previous_spy_close >= previous_spy_sma and spy_close < spy_sma:
                self.MarketOrder(self.spy, -self.spy_lot)
                self.spy_lot = 0
        elif previous_spy_close <= previous_spy_sma and spy_close > spy_sma:
            quantity = self.CalculateOrderQuantity(self.spy, self.SPY_ALLOCATION)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.aapl_lot)
                self.aapl_lot = 0
        elif (
            self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= self.AAPL_PURCHASE_DOLLARS
        ):
            quantity = int(self.AAPL_PURCHASE_DOLLARS // aapl_close)
            if quantity > 0:
                self.MarketOrder(self.aapl, quantity)
                self.aapl_lot = quantity

