class ParallelSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # One extra close is retained so both sides of an SMA crossing can be
        # evaluated using their respective 100-day averages.
        self.spy_closes = deque(maxlen=101)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False
        self.order_strategy = {}

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        spy_bar = data.Bars[self.spy] if self.spy in data.Bars else None
        aapl_bar = data.Bars[self.aapl] if self.aapl in data.Bars else None

        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close

        # A day is indivisible for rule evaluation: all five bars must exist.
        if any(symbol not in data.Bars for symbol in self.symbols):
            return
        if self.IsWarmingUp:
            return
        if len(self.spy_closes) < 101 or not self.aapl_rsi.IsReady:
            return

        spy_close = float(spy_bar.Close)
        aapl_close = float(aapl_bar.Close)
        closes = list(self.spy_closes)
        previous_spy_close = closes[-2]
        previous_sma = sum(closes[-101:-1]) / 100.0
        current_sma = sum(closes[-100:]) / 100.0

        spy_crossed_below = (
            previous_spy_close >= previous_sma and spy_close < current_sma
        )
        spy_crossed_above = (
            previous_spy_close <= previous_sma and spy_close > current_sma
        )

        # All exits are evaluated before either strategy is allowed to enter.
        if self.spy_lot > 0 and not self.spy_order_pending and spy_crossed_below:
            self._submit_order(self.spy, -self.spy_lot, "spy")

        if (
            self.aapl_lot > 0
            and not self.aapl_order_pending
            and self.aapl_rsi.Current.Value > 60
        ):
            self._submit_order(self.aapl, -self.aapl_lot, "aapl")

        if self.spy_lot == 0 and not self.spy_order_pending and spy_crossed_above:
            quantity = self.CalculateOrderQuantity(self.spy, 1.0)
            if quantity > 0:
                self._submit_order(self.spy, quantity, "spy")

        if (
            self.aapl_lot == 0
            and not self.aapl_order_pending
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20_000
        ):
            quantity = floor(20_000 / aapl_close)
            if quantity > 0:
                self._submit_order(self.aapl, quantity, "aapl")

    def _submit_order(self, symbol: Symbol, quantity: int, strategy: str):
        ticket = self.MarketOrder(symbol, quantity)
        self.order_strategy[ticket.OrderId] = strategy
        if strategy == "spy":
            self.spy_order_pending = True
        else:
            self.aapl_order_pending = True

    def OnOrderEvent(self, order_event: OrderEvent):
        strategy = self.order_strategy.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.Status in [OrderStatus.PartiallyFilled, OrderStatus.Filled]:
            if strategy == "spy":
                self.spy_lot += order_event.FillQuantity
            else:
                self.aapl_lot += order_event.FillQuantity

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ]:
            if strategy == "spy":
                self.spy_order_pending = False
            else:
                self.aapl_order_pending = False
            del self.order_strategy[order_event.OrderId]

