class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14)

        self.previous_closes = {}
        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

        # The specified percentage is represented here as the whole portfolio.
        self.strategy_a_portfolio_percentage = 1.0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        spy_bar = bars.get("SPY")
        aapl_bar = bars.get("AAPL")

        old_spy_close = self.previous_spy_close
        old_spy_sma = self.previous_spy_sma

        if spy_bar is not None:
            self.spy_sma.update(spy_bar.end_time, spy_bar.close)
            if self.spy_sma.is_ready:
                self.previous_spy_close = spy_bar.close
                self.previous_spy_sma = self.spy_sma.current.value

        if aapl_bar is not None:
            previous_aapl_close = self.previous_closes.get("AAPL")
            if previous_aapl_close is not None:
                if aapl_bar.close < previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.close

        if len(bars) != len(self.symbols):
            return
        if not self.spy_sma.is_ready or not self.aapl_rsi.is_ready:
            return
        if old_spy_close is None or old_spy_sma is None:
            return

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and not self.spy_order_pending:
            crossed_below = (
                old_spy_close >= old_spy_sma
                and spy_bar.close < self.spy_sma.current.value
            )
            if crossed_below:
                self.spy_order_pending = True
                self.market_order(
                    self.symbols["SPY"], -self.spy_lot, tag="strategy-a-sell"
                )

        if self.aapl_lot > 0 and not self.aapl_order_pending:
            if self.aapl_rsi.current.value > 60:
                self.aapl_order_pending = True
                self.market_order(
                    self.symbols["AAPL"], -self.aapl_lot, tag="strategy-b-sell"
                )

        if self.spy_lot == 0 and not self.spy_order_pending:
            crossed_above = (
                old_spy_close <= old_spy_sma
                and spy_bar.close > self.spy_sma.current.value
            )
            if crossed_above:
                target_value = (
                    self.portfolio.total_portfolio_value
                    * self.strategy_a_portfolio_percentage
                )
                quantity = int(target_value / spy_bar.close)
                if quantity > 0:
                    self.spy_order_pending = True
                    self.market_order(
                        self.symbols["SPY"], quantity, tag="strategy-a-buy"
                    )

        if self.aapl_lot == 0 and not self.aapl_order_pending:
            if self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
                quantity = int(20_000 / aapl_bar.close)
                if quantity > 0:
                    self.aapl_order_pending = True
                    self.market_order(
                        self.symbols["AAPL"], quantity, tag="strategy-b-buy"
                    )

    def on_order_event(self, order_event: OrderEvent):
        order = self.transactions.get_order_by_id(order_event.order_id)
        if order is None:
            return

        if order.tag.startswith("strategy-a-"):
            if order_event.status in [
                OrderStatus.PARTIALLY_FILLED,
                OrderStatus.FILLED,
            ]:
                self.spy_lot += order_event.fill_quantity
            if order_event.status == OrderStatus.FILLED:
                self.spy_order_pending = False
            elif order_event.status in [OrderStatus.CANCELED, OrderStatus.INVALID]:
                self.spy_order_pending = False

        elif order.tag.startswith("strategy-b-"):
            if order_event.status in [
                OrderStatus.PARTIALLY_FILLED,
                OrderStatus.FILLED,
            ]:
                self.aapl_lot += order_event.fill_quantity
            if order_event.status == OrderStatus.FILLED:
                self.aapl_order_pending = False
            elif order_event.status in [OrderStatus.CANCELED, OrderStatus.INVALID]:
                self.aapl_order_pending = False

