class StrategySystemAlgorithm(QCAlgorithm):
    """Two independent, privately accounted strategy lots."""

    STRATEGY_A_PORTFOLIO_PERCENT = 1.0
    STRATEGY_B_CASH_AMOUNT = 20000.0

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1000000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_closes = deque(maxlen=4)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {}
        complete_slice = True
        for ticker, symbol in self.symbols.items():
            if not data.bars.contains_key(symbol):
                complete_slice = False
                continue
            bars[ticker] = data.bars[symbol]

        # Market-state quantities are updated whenever their ticker has a bar,
        # even when another missing ticker prevents all rule evaluation.
        spy = bars.get("SPY")
        if spy is not None:
            self.spy_closes.append(float(spy.close))

        aapl = bars.get("AAPL")
        if aapl is not None:
            close = float(aapl.close)
            self.aapl_closes.append(close)
            self.aapl_rsi.update(aapl.end_time, close)

        if not complete_slice:
            return

        # Sells are evaluated before buys across the system.
        if self.strategy_a_shares > 0 and len(self.spy_closes) == 101:
            previous_sma = sum(list(self.spy_closes)[:-1][-100:]) / 100.0
            current_sma = sum(list(self.spy_closes)[-100:]) / 100.0
            previous_close = self.spy_closes[-2]
            current_close = self.spy_closes[-1]
            if previous_close >= previous_sma and current_close < current_sma:
