        self.aapl_lot = 0

        # The strategy specification does not state a numeric percentage. This
        # parameter expresses it as a portfolio fraction and defaults to 100%.
        parameter = self.GetParameter("strategy_a_portfolio_percentage")
        self.spy_target = float(parameter) if parameter else 1.0

    def OnData(self, data: Slice):
        bars = {}
        complete_day = True
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]
            else:
                complete_day = False

        spy_crossed_above = False
        spy_crossed_below = False
        if "SPY" in bars:
            close = float(bars["SPY"].Close)
            if len(self.spy_closes) >= 100:
                previous_hundred = list(self.spy_closes)[-100:]
                yesterday_close = self.spy_closes[-1]
                yesterday_sma = sum(previous_hundred) / 100.0
                today_sma = (sum(previous_hundred[1:]) + close) / 100.0
                spy_crossed_above = yesterday_close <= yesterday_sma and close > today_sma
                spy_crossed_below = yesterday_close >= yesterday_sma and close < today_sma
            self.spy_closes.append(close)

        if "AAPL" in bars:
            bar = bars["AAPL"]
            close = float(bar.Close)
            if self.aapl_previous_close is not None:
                if close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = close
            self.aapl_rsi.Update(bar.EndTime, bar.Close)

        if not complete_day:
            return

        if self.spy_lot > 0 and spy_crossed_below:
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if len(self.spy_closes) == 101 and self.spy_lot == 0 and spy_crossed_above:
            quantity = self.CalculateOrderQuantity(self.symbols["SPY"], self.spy_target)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if (
            self.aapl_lot == 0
            and self.aapl_rsi.IsReady
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20_000
        ):
            quantity = math.floor(20_000 / float(bars["AAPL"].Close))
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

