        }

        # Strategy A invests 100% of total portfolio value when its lot is empty.
        self.strategy_a_fraction = 1.0
        self.strategy_a_shares = 0
        self.spy_closes = deque(maxlen=101)

        self.strategy_b_shares = 0
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14)

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bar = data.bars[symbol]
                bars[ticker] = bar

                # Market-state calculations continue even when another ticker's
                # bar is absent and rule evaluation is skipped for the day.
                if ticker == "SPY":
                    self.spy_closes.append(float(bar.close))
                elif ticker == "AAPL":
                    close = float(bar.close)
                    if self.aapl_previous_close is not None:
                        if close < self.aapl_previous_close:
                            self.aapl_red_streak += 1
                        else:
                            self.aapl_red_streak = 0
                    self.aapl_previous_close = close
                    self.aapl_rsi.update(bar.end_time, close)

        if len(bars) != len(self.symbols):
            return

        # Sells are evaluated before buys. The two lots otherwise run in
        # parallel and independently.
        self._evaluate_strategy_a(float(bars["SPY"].close))
        self._evaluate_strategy_b(float(bars["AAPL"].close))

    def _evaluate_strategy_a(self, close):
        if len(self.spy_closes) < 101:
            return

        closes = list(self.spy_closes)
        yesterday_sma = sum(closes[-101:-1]) / 100.0
        today_sma = sum(closes[-100:]) / 100.0
        crossed_above = closes[-2] <= yesterday_sma and close > today_sma
        crossed_below = closes[-2] >= yesterday_sma and close < today_sma

        if self.strategy_a_shares > 0:
            if crossed_below:
                self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0
            return

        if crossed_above:
            target_value = self.portfolio.total_portfolio_value * self.strategy_a_fraction
            shares = floor(target_value / close)
            if shares > 0:
                self.market_order(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

    def _evaluate_strategy_b(self, close):
        if not self.aapl_rsi.is_ready:
            return

        if self.strategy_b_shares > 0:
            if self.aapl_rsi.current.value > 60:
                self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0
            return

        if self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
            shares = floor(20_000 / close)
            if shares > 0:
                self.market_order(self.symbols["AAPL"], shares)
                self.strategy_b_shares = shares

