class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

        # "Invest a percentage" is represented as the whole portfolio allocation.
        self.spy_allocation = 1.0

        # Warm-up supplies enough pre-start observations for every rule to be ready
        # on the first backtest bar without allowing warm-up trades.
        self.SetWarmUp(120, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities continue to advance whenever their own data exists.
        if "SPY" in bars:
            self.spy_closes.append(float(bars["SPY"].Close))

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(data.Time, aapl_close)

        if self.IsWarmingUp or len(bars) != len(self.symbols):
            return
        if len(self.spy_closes) < 101 or not self.aapl_rsi.IsReady:
            return

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        previous_spy_close = self.spy_closes[-2]
        current_spy_close = self.spy_closes[-1]
        previous_spy_sma = sum(list(self.spy_closes)[:-1]) / 100.0
        current_spy_sma = sum(list(self.spy_closes)[-100:]) / 100.0

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and not self.spy_order_pending:
            if previous_spy_close >= previous_spy_sma and current_spy_close < current_spy_sma:
                self.spy_order_pending = True
                self.MarketOrder(spy, -self.spy_lot, tag="Strategy A sell")

        if self.aapl_lot > 0 and not self.aapl_order_pending:
            if self.aapl_rsi.Current.Value > 60:
                self.aapl_order_pending = True
                self.MarketOrder(aapl, -self.aapl_lot, tag="Strategy B sell")

        if self.spy_lot == 0 and not self.spy_order_pending:
            if previous_spy_close <= previous_spy_sma and current_spy_close > current_spy_sma:
                quantity = self.CalculateOrderQuantity(spy, self.spy_allocation)
                if quantity > 0:
                    self.spy_order_pending = True
                    self.MarketOrder(spy, quantity, tag="Strategy A buy")

        if self.aapl_lot == 0 and not self.aapl_order_pending:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                quantity = floor(20_000 / float(bars["AAPL"].Close))
                if quantity > 0:
                    self.aapl_order_pending = True
                    self.MarketOrder(aapl, quantity, tag="Strategy B buy")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (OrderStatus.Filled, OrderStatus.PartiallyFilled):
            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                if order_event.Symbol == self.symbols["SPY"]:
                    self.spy_order_pending = False
                elif order_event.Symbol == self.symbols["AAPL"]:
                    self.aapl_order_pending = False
            return

        fill_quantity = int(order_event.FillQuantity)
        if order_event.Symbol == self.symbols["SPY"]:
            self.spy_lot = max(0, self.spy_lot + fill_quantity)
            if order_event.Status == OrderStatus.Filled:
                self.spy_order_pending = False
        elif order_event.Symbol == self.symbols["AAPL"]:
            self.aapl_lot = max(0, self.aapl_lot + fill_quantity)
            if order_event.Status == OrderStatus.Filled:
                self.aapl_order_pending = False
